void ui_option_item_set_label(void *item,const char *text){u32 value=0,scratch=0;if(!item)return;((StrCtor)SEAM_StrCtor)(&value,text?text:"",&scratch);((StrAssign)SEAM_StrAssign)(&((UiOptionsRowView*)item)->localized_label,&value);((StrDtor)SEAM_StrDtor)(&value);}
