void ui_screen_add_tab(void *screen,UiShared *tab_button){if(screen&&tab_button)((PushFn)SEAM_SharedPush)(&((UiScreenView*)screen)->tabs,(Shared*)tab_button);}
int ui_screen_selected_tab(void *screen){UiScreenView *v=(UiScreenView*)screen;return v?v->selected_tab:-1;}
void ui_screen_set_tab(void *screen,int tab_index){UiScreenView *v=(UiScreenView*)screen;unsigned count;if(!v||!v->tabs.begin||v->tabs.end<=v->tabs.begin)return;count=(unsigned)(v->tabs.end-v->tabs.begin);if(tab_index<0||(unsigned)tab_index>=count)return;v->selected_tab=tab_index;}
int ui_screen_cycle_tab(void *screen,int delta){unsigned count=ui_screen_tab_count(screen);int current,next;if(count<=1)return -1;current=ui_screen_selected_tab(screen);if(current<0)current=0;next=(current+delta)%(int)count;if(next<0)next+=(int)count;ui_screen_set_tab(screen,next);ui_screen_update_tab_buttons(screen);return next;}
void ui_screen_update_tab_buttons(void *screen){unsigned count=ui_screen_tab_count(screen),i;int selected=ui_screen_selected_tab(screen);for(i=0;i<count;i++){void *tab=ui_screen_tab_at(screen,i);if(tab)ui_button_set_latched(tab,(int)i==selected);}}
unsigned ui_screen_tab_count(void *screen){UiScreenView *v=(UiScreenView*)screen;if(!v||!v->tabs.begin||v->tabs.end<=v->tabs.begin)return 0;return(unsigned)(v->tabs.end-v->tabs.begin);}
void *ui_screen_tab_at(void *screen,unsigned index){UiScreenView *v=(UiScreenView*)screen;if(!v||!v->tabs.begin||v->tabs.begin+index>=v->tabs.end)return 0;return v->tabs.begin[index].object;}
void ui_screen_add_selectable(void*screen,void*object){UiSharedVector*v=&((UiScreenView*)screen)->buttons;UiShared*it;for(it=v->begin;it&&it<v->end;it++)if(it->object==object){((PushFn)SEAM_SharedPush)(&((UiScreenView*)screen)->selectable_components,(Shared*)it);return;}}
void ui_screen_set_selection(void*screen,unsigned index){UiScreenView*v=(UiScreenView*)screen;unsigned count=(unsigned)(v->selectable_components.end-v->selectable_components.begin);if(!count)return;v->selectable_selection=(int)(index%count);((ThisFn)SEAM_Screen_updateComponentSelections)(screen);}
void *ui_screen_selected(void*screen){UiScreenView*v=(UiScreenView*)screen;int i=v->selectable_selection;return i>=0&&v->selectable_components.begin+i<v->selectable_components.end?v->selectable_components.begin[i].object:0;}
int ui_screen_navigate(void*screen,int direction){UiScreenView*v=(UiScreenView*)screen;UiShared*it;UiElementView*selected,*candidate;unsigned index=0,best_index=0;int selected_x,selected_y,dx,dy,primary,secondary,score,best_score=0x7fffffff,found=0;if(!v||!v->selectable_components.begin||v->selectable_components.end<=v->selectable_components.begin)return 0;selected=(UiElementView*)ui_screen_selected(screen);if(!selected)return 0;selected_x=selected->x+selected->width/2;selected_y=selected->y+selected->height/2;for(it=v->selectable_components.begin;it<v->selectable_components.end;it++,index++){candidate=(UiElementView*)it->object;if(!candidate||candidate==selected||!candidate->active||!candidate->visible)continue;dx=candidate->x+candidate->width/2-selected_x;dy=candidate->y+candidate->height/2-selected_y;if(direction==UI_NAV_LEFT){if(dx>=0)continue;primary=-dx;secondary=dy<0?-dy:dy;}else if(direction==UI_NAV_RIGHT){if(dx<=0)continue;primary=dx;secondary=dy<0?-dy:dy;}else if(direction==UI_NAV_UP){if(dy>=0)continue;primary=-dy;secondary=dx<0?-dx:dx;}else if(direction==UI_NAV_DOWN){if(dy<=0)continue;primary=dy;secondary=dx<0?-dx:dx;}else return 0;if(secondary>primary*2+8)continue;score=primary*primary+secondary*secondary*4;if(score<best_score){best_score=score;best_index=index;found=1;}}if(!found)return 0;ui_screen_set_selection(screen,best_index);return 1;}
void ui_container_add_raw(void *container,void *child,int selectable){((ContainerAddChild)SEAM_ContainerAddChild)(container,child,selectable);}
