void ui_int_vector_push(void *vector,int value){((void(*)(void*,const int*))SEAM_PushRow)(vector,&value);}
int ui_grid_move_appended_row_before(void *container,UiIntVector*rows,void*first,void*second,void*target){UiSharedVector*children;UiShared saved_first,saved_second;unsigned child_count,row_count,target_child,target_row,offset,i;if(!container||!rows||!first||!second||!target)return 0;children=&((UiContainerView*)container)->children;if(!children->begin||!children->end||children->end-children->begin<4||!rows->begin||!rows->end||rows->end<=rows->begin)return 0;child_count=(unsigned)(children->end-children->begin);row_count=(unsigned)(rows->end-rows->begin);if(children->begin[child_count-2].object!=first||children->begin[child_count-1].object!=second)return 0;for(target_child=0;target_child<child_count-2;target_child++)if(children->begin[target_child].object==target)break;if(target_child==child_count-2||target_child==0)return 0;target_child--;offset=0;for(target_row=0;target_row<row_count;target_row++){unsigned width=(unsigned)rows->begin[target_row];if(target_child<offset+width)break;offset+=width;}if(target_row>=row_count-1)return 0;saved_first=children->begin[child_count-2];saved_second=children->begin[child_count-1];for(i=child_count-2;i>target_child;i--)children->begin[i+1]=children->begin[i-1];children->begin[target_child]=saved_first;children->begin[target_child+1]=saved_second;{int saved_width=rows->begin[row_count-1];for(i=row_count-1;i>target_row;i--)rows->begin[i]=rows->begin[i-1];rows->begin[target_row]=saved_width;}return 1;}
