void ui_capture_vector(UiSharedVector*v,void **objects,u8 *active,u8 *visible,u32 *count,u32 capacity){UiShared*it,*end;if(!v||!count)return;it=v->begin;end=v->end;while(it&&it<end&&*count<capacity){if(it->object){objects[*count]=it->object;ui_element_capture(it->object,&active[*count],&visible[*count]);(*count)++;}it++;}}
